/**
 * Static interference at sequence keyframes (PB-1185, research B.4 v2).
 *
 * For each keyframe (`sequence/keyframes.ts`: assembled, just before each
 * step, each joint at its stops) every placed body and fastener is posed and
 * pairs are tested:
 *
 *   walls    an enclosure generated by ext-enclosure-cad, when the project has
 *            one and a CAD Python runtime is present: its voxel field
 *            (`./voxel.ts`), ±1 cell;
 *   pairs    everything else: world boxes first (AABB), then the two meshes'
 *            BVHs (`./bvh.ts`); the fallback for the walls too when the voxel
 *            field cannot run. The report says which ran.
 *
 * A pair whose surfaces touch or cross is a hit; its penetration depth is
 * estimated from up to SAMPLES vertices and triangle centres of each mesh
 * found inside the other (ray parity), as their distance to the other's
 * surface: a lower bound (DEFAULT). Below CONTACT_MM it is "contact"
 * (tessellation and modelled zero-clearance fits), above it "interference".
 * Pairs a UHD link mates (its two bodies, its fastener stack) are marked
 * `intended`: a screw in its hole, a board on its standoffs.
 *
 * Pair results are reused across keyframes when neither body moved relative
 * to the other, which is most pairs at most keyframes. Caps (DEFAULT): a
 * wall-clock budget, triangles per body (mesh.ts), voxels (voxel.ts).
 * Units: mm, Z up; mesh.ts converts from glTF at the boundary.
 */
import { existsSync } from "node:fs";
import { join } from "node:path";
import type { Assembly } from "@deltarobotics/uhd";
import { resolvePartFile } from "../part-files.js";
import type { Project } from "../project.js";
import { hardwareKeys } from "../sequence/generate.js";
import { keyframeAt, poseCore, posed, relative, resolveCore, sequenceKeyframes, type CoreResolved, type Keyframe } from "../sequence/keyframes.js";
import type { SequenceFile } from "../sequence/types.js";
import { TriBVH, applyRM } from "./bvh.js";
import { invertRigid, mul, type M4 } from "./frames.js";
import { readBodyMesh } from "./mesh.js";
import { linkedPairs, placedBodies } from "./project.js";
import { VOXEL_DEFAULTS, cadPython, runVoxel, type VoxelQuery } from "./voxel.js";

export const INTERFERENCE_SCHEMA = "protoboard.interference/v0";
/** DEFAULT: contact below this depth (mm); vertices and centres sampled per mesh; the whole run's time budget (s). */
export const INTERFERENCE_DEFAULTS = { contactMm: 0.1, samples: 512, maxSeconds: 120 };

export interface InterferenceBody {
  key: string;
  instance: string;
  file: string;
  /** Placement (body frame to world, row-major, mm). */
  matrix: number[];
  bvh: TriBVH;
  via: "view-sidecar" | "source";
  hardware?: { linkId: string };
  /** An enclosure ext-enclosure-cad generated (its walls go to the voxel field). */
  enclosure?: boolean;
}

export interface InterferenceHit {
  a: string;
  b: string;
  status: "interference" | "contact";
  /** Penetration estimate (mm): a lower bound from sampled points. */
  depthMm: number;
  /** A point at the hit (world, mm). */
  at?: number[];
  /** The UHD link that mates the two (intended contact). */
  intended?: string;
  method: "bvh" | "voxel";
  /** The wall part a voxel hit is in. */
  wall?: string;
}

export interface KeyframeReport {
  id: string;
  label: string;
  t: number;
  ms: number;
  /** Pairs whose world boxes overlap; of those, tested now and reused from an earlier keyframe. */
  candidates: number;
  tested: number;
  reused: number;
  hits: InterferenceHit[];
  /** Bodies left out at this keyframe (planned parts while apart). */
  excluded: string[];
}

export interface InterferenceReport {
  schema: typeof INTERFERENCE_SCHEMA;
  method: { pairs: "bvh"; walls?: "voxel" | "bvh"; voxel?: { resolutionMm?: number; cells?: number; ms: number; error?: string } };
  defaults: typeof INTERFERENCE_DEFAULTS & { voxel: typeof VOXEL_DEFAULTS };
  bodies: number;
  triangles: number;
  timings: { loadMs: number; bvhMs: number; checkMs: number };
  keyframes: KeyframeReport[];
  /** Totals over keyframes (non-intended interferences are the findings). */
  counts: { interference: number; intendedInterference: number; contact: number };
  skipped: { instance: string; reason: string }[];
  truncated?: string;
}

/** Load every placed body and fastener with a real model, one BVH per file. */
export async function loadInterferenceBodies(p: Project, asm: Assembly): Promise<{ bodies: InterferenceBody[]; skipped: { instance: string; reason: string }[]; loadMs: number; bvhMs: number; triangles: number }> {
  const { bodies: placed, skipped } = placedBodies(p, asm);
  const enclosures = new Set(p.capabilities.filter((b) => b.provider === "@protoboardai/ext-enclosure-cad" && !b.problem).flatMap((b) => b.instances));
  const byFile = new Map<string, { bvh: TriBVH; via: InterferenceBody["via"]; triangles: number }>();
  let loadMs = 0, bvhMs = 0, triangles = 0;
  const load = async (file: string) => {
    let hit = byFile.get(file);
    if (!hit) {
      const t0 = performance.now();
      const mesh = await readBodyMesh(file, p.root);
      const t1 = performance.now();
      hit = { bvh: new TriBVH(mesh.positions, mesh.indices), via: mesh.via, triangles: mesh.triangles };
      loadMs += t1 - t0;
      bvhMs += performance.now() - t1;
      byFile.set(file, hit);
    }
    return hit;
  };
  const bodies: InterferenceBody[] = [];
  for (const b of placed) {
    try {
      const m = await load(b.file);
      bodies.push({ key: b.key, instance: b.instance, file: b.file, matrix: b.matrix, bvh: m.bvh, via: m.via, ...(enclosures.has(b.instance) ? { enclosure: true } : {}) });
      triangles += m.triangles;
    } catch (e) {
      skipped.push({ instance: b.key, reason: (e as Error).message.split("\n")[0] });
    }
  }
  const keys = hardwareKeys(asm.hardware);
  for (const [i, h] of asm.hardware.entries()) {
    const r = resolvePartFile(p, { part: h.def.id }, "model", { formats: ["glb"] });
    if (!r.file || r.placeholder || !existsSync(r.file)) {
      skipped.push({ instance: keys[i], reason: r.placeholder ? "placeholder" : "no model file" });
      continue;
    }
    try {
      const m = await load(r.file);
      bodies.push({ key: keys[i], instance: keys[i], file: r.file, matrix: h.matrix as unknown as number[], bvh: m.bvh, via: m.via, hardware: { linkId: h.linkId } });
      triangles += m.triangles;
    } catch (e) {
      skipped.push({ instance: keys[i], reason: (e as Error).message.split("\n")[0] });
    }
  }
  return { bodies, skipped, loadMs: Math.round(loadMs), bvhMs: Math.round(bvhMs), triangles };
}

/** World box of a body's mesh at a pose. */
function worldBox(b: InterferenceBody, pose: readonly number[]): number[] {
  const bb = b.bvh.bounds;
  const lo = [Infinity, Infinity, Infinity], hi = [-Infinity, -Infinity, -Infinity];
  for (const x of [bb[0], bb[3]]) for (const y of [bb[1], bb[4]]) for (const z of [bb[2], bb[5]]) {
    const w = applyRM(pose, [x, y, z]);
    for (let k = 0; k < 3; k++) {
      lo[k] = Math.min(lo[k], w[k]);
      hi[k] = Math.max(hi[k], w[k]);
    }
  }
  return [...lo, ...hi];
}

/** Sample points of a mesh: its vertices and triangle centres, evenly strided down to `n`. */
function samplesOf(bvh: TriBVH, n: number): number[][] {
  const out: number[][] = [];
  const P = bvh.positions, I = bvh.indices;
  const verts = P.length / 3;
  const half = Math.max(1, Math.floor(n / 2));
  const sv = Math.max(1, Math.floor(verts / half));
  for (let i = 0; i < verts; i += sv) out.push([P[i * 3], P[i * 3 + 1], P[i * 3 + 2]]);
  const tris = I.length / 3;
  const st = Math.max(1, Math.floor(tris / half));
  for (let t = 0; t < tris; t += st) {
    const a = I[t * 3] * 3, b = I[t * 3 + 1] * 3, c = I[t * 3 + 2] * 3;
    out.push([(P[a] + P[b] + P[c]) / 3, (P[a + 1] + P[b + 1] + P[c + 1]) / 3, (P[a + 2] + P[b + 2] + P[c + 2]) / 3]);
  }
  return out;
}

/** Deepest sample of `inner` (carried into `outer`'s frame by m) inside `outer`, as distance to its surface. */
function deepest(outer: TriBVH, inner: TriBVH, m: M4, n: number): { depth: number; at?: number[] } {
  let depth = 0;
  let at: number[] | undefined;
  const bb = outer.bounds;
  for (const s of samplesOf(inner, n)) {
    const p = applyRM(m, s);
    if (p[0] < bb[0] || p[1] < bb[1] || p[2] < bb[2] || p[0] > bb[3] || p[1] > bb[4] || p[2] > bb[5]) continue;
    if (!outer.inside(p)) continue;
    const d = outer.closest(p);
    if (d > depth) {
      depth = d;
      at = p;
    }
  }
  return { depth, ...(at ? { at } : {}) };
}

/** Test one pair at given world poses; undefined when they do not touch. */
export function testPair(A: InterferenceBody, B: InterferenceBody, poseA: M4, poseB: M4, opts = INTERFERENCE_DEFAULTS): Omit<InterferenceHit, "a" | "b" | "intended" | "method"> | undefined {
  const mBA = relative(poseA, poseB); // B's frame into A's
  const touch = A.bvh.intersects(B.bvh, mBA, 1);
  // no surface contact: only a body wholly inside the other can still interfere (a box inside a box)
  if (!touch.hits && !nests(A.bvh.bounds, B.bvh.bounds, mBA) && !nests(B.bvh.bounds, A.bvh.bounds, invertRigid(mBA))) return undefined;
  const inB = deepest(A.bvh, B.bvh, mBA, opts.samples);
  const mAB = invertRigid(mBA);
  const inA = deepest(B.bvh, A.bvh, mAB, opts.samples);
  if (!touch.hits && !inA.depth && !inB.depth) return undefined;
  const depth = Math.max(inA.depth, inB.depth);
  const local = inB.depth >= inA.depth ? inB.at : inA.at ? applyRM(mBA, inA.at) : undefined;
  const pt = local ?? touch.points[0];
  return { status: depth >= opts.contactMm ? "interference" : "contact", depthMm: Math.round(depth * 1000) / 1000, ...(pt ? { at: applyRM(poseA, pt).map((x) => Math.round(x * 100) / 100) } : {}) };
}

/** Is the box `inner` (carried by m) inside the box `outer`? */
function nests(outer: number[], inner: number[], m: M4): boolean {
  for (const x of [inner[0], inner[3]]) for (const y of [inner[1], inner[4]]) for (const z of [inner[2], inner[5]]) {
    const p = applyRM(m, [x, y, z]);
    if (p[0] < outer[0] || p[1] < outer[1] || p[2] < outer[2] || p[0] > outer[3] || p[1] > outer[4] || p[2] > outer[5]) return false;
  }
  return true;
}

const round6 = (m: readonly number[]) => m.map((x) => Math.round(x * 1e4) / 1e4).join(",");

export interface InterferenceOptions {
  /** One keyframe id ("assembled", "step:<id>", "joint:<id>@min") or a t in [0, 1]; default every keyframe. */
  at?: string;
  contactMm?: number;
  samples?: number;
  maxSeconds?: number;
  /** Leave the voxel field out (BVH for everything). */
  noVoxel?: boolean;
  voxelMm?: number;
  maxVoxels?: number;
}

/** Run the check over the sequence's keyframes. */
export async function runInterference(p: Project, asm: Assembly, file: SequenceFile, options: InterferenceOptions = {}): Promise<InterferenceReport> {
  const opts = { contactMm: options.contactMm ?? INTERFERENCE_DEFAULTS.contactMm, samples: options.samples ?? INTERFERENCE_DEFAULTS.samples, maxSeconds: options.maxSeconds ?? INTERFERENCE_DEFAULTS.maxSeconds };
  const start = performance.now();
  const loaded = await loadInterferenceBodies(p, asm);
  const r: CoreResolved = resolveCore(asm, file);
  let frames: Keyframe[];
  if (options.at !== undefined) {
    const k = keyframeAt(r, options.at);
    if (!k) throw new Error(`no keyframe "${options.at}" (keyframes: ${sequenceKeyframes(r).slice(0, 6).map((x) => x.id).join(", ")}, …; or a number t from 0 to 1)`);
    frames = [k];
  } else frames = sequenceKeyframes(r);
  const linked = linkedPairs(asm);
  const pairKey = (a: string, b: string) => [a, b].sort().join("~");
  // a fastener harness's parts are meant to touch every body any link through that harness joins (a stack's screws
  // pass through the ESC and the FC), and each other
  const harnessOf = (m: Assembly["mates"][number]) => m.harnessPath?.join("/") ?? m.harness;
  const throughHarness = new Map<string, { link: string; keys: Set<string> }>();
  for (const m of asm.mates) {
    const h = harnessOf(m);
    if (!h) continue;
    const e = throughHarness.get(h) ?? { link: m.linkId, keys: new Set<string>() };
    for (const end of [m.a, m.b]) e.keys.add(end.path.join("/") + (end.frame.artifact ? `#${end.frame.artifact}` : ""));
    throughHarness.set(h, e);
  }
  const hwHarness = new Map(asm.hardware.map((h, i) => [hardwareKeys(asm.hardware)[i], h.harness]));
  const intendedOf = (A: InterferenceBody, B: InterferenceBody): string | undefined => {
    const direct = linked.get(pairKey(A.key, B.key));
    if (direct) return direct;
    const ha = hwHarness.get(A.key), hb = hwHarness.get(B.key);
    if (ha && hb && ha === hb) return A.hardware!.linkId;
    for (const [hw, other] of [[A, B], [B, A]] as const) {
      const h = hwHarness.get(hw.key);
      if (!h || hwHarness.has(other.key)) continue;
      if (throughHarness.get(h)?.keys.has(other.key)) return hw.hardware!.linkId;
      const own = asm.hardware.find((x) => x.linkId === hw.hardware!.linkId);
      if (own && (own.structure === other.key || own.mounted === other.key)) return hw.hardware!.linkId;
    }
    return undefined;
  };
  // the voxel field for an enclosure's walls, when one exists and Python is there
  const enclosure = loaded.bodies.find((b) => b.enclosure);
  const encExt = p.extensions.find((e) => e.package === "@protoboardai/ext-enclosure-cad");
  const python = cadPython(p.root);
  const useVoxel = !!enclosure && !!encExt && !!python && !options.noVoxel;
  const method: InterferenceReport["method"] = { pairs: "bvh", ...(enclosure ? { walls: useVoxel ? "voxel" : "bvh" } : {}) };
  // poses per keyframe
  const poses = frames.map((k) => {
    const pose = poseCore(r, k.t, k.joints ?? {});
    return { k, pose, world: new Map(loaded.bodies.map((b) => [b.key, posed(pose.deltas.get(b.key), b.matrix)])) };
  });
  let voxelHits = new Map<string, InterferenceHit>(); // query id -> hit
  if (useVoxel) {
    const queries: VoxelQuery[] = [];
    const seen = new Set<string>();
    for (const { pose, world } of poses) {
      const encInv = invertRigid(world.get(enclosure!.key)!);
      for (const b of loaded.bodies) {
        if (b === enclosure || pose.apart.has(b.key)) continue;
        const m = mul(encInv, world.get(b.key)!);
        const id = `${b.key}|${round6(m)}`;
        if (seen.has(id)) continue;
        seen.add(id);
        queries.push({ id, glb: b.file, matrix: m });
      }
    }
    const run = await runVoxel({ python: python!, fitPy: join(encExt!.root, "py"), walls: enclosure!.file, queries, scratch: join(p.root, ".protoboard", "build", "interference"), resolutionMm: options.voxelMm, maxCells: options.maxVoxels, timeoutS: opts.maxSeconds });
    method.voxel = { ...(run.resolutionMm ? { resolutionMm: run.resolutionMm } : {}), ...(run.cells ? { cells: run.cells } : {}), ms: run.ms, ...(run.error ? { error: run.error } : {}) };
    if (!run.ok) method.walls = "bvh";
    const res = run.resolutionMm ?? VOXEL_DEFAULTS.resolutionMm;
    for (const a of run.answers) {
      const key = a.id.split("|")[0];
      // one cell either way, as fit.py: inside past one cell is a collision, within it a contact
      if (a.minClearanceMm >= 0) continue;
      voxelHits.set(a.id, { a: enclosure!.key, b: key, status: a.minClearanceMm < -res ? "interference" : "contact", depthMm: Math.round(-a.minClearanceMm * 1000) / 1000, ...(a.at.length ? { at: a.at } : {}), method: "voxel", ...(a.wall ? { wall: a.wall } : {}) });
    }
    if (!run.ok) voxelHits = new Map();
  }
  const cache = new Map<string, Omit<InterferenceHit, "a" | "b" | "intended" | "method"> | null>();
  const reports: KeyframeReport[] = [];
  const counts = { interference: 0, intendedInterference: 0, contact: 0 };
  let truncated: string | undefined;
  for (const { k, pose, world } of poses) {
    const t0 = performance.now();
    if ((t0 - start) / 1000 > opts.maxSeconds) {
      truncated = `stopped at keyframe "${k.id}": over the ${opts.maxSeconds} s budget (DEFAULT; --max-seconds)`;
      break;
    }
    const active = loaded.bodies.filter((b) => !pose.apart.has(b.key));
    const boxes = new Map(active.map((b) => [b.key, worldBox(b, world.get(b.key)!)]));
    // sweep along x for overlapping boxes
    const sorted = [...active].sort((a, b) => boxes.get(a.key)![0] - boxes.get(b.key)![0]);
    const hits: InterferenceHit[] = [];
    let candidates = 0, tested = 0, reused = 0;
    for (let i = 0; i < sorted.length; i++) {
      const A = sorted[i];
      const ba = boxes.get(A.key)!;
      for (let j = i + 1; j < sorted.length; j++) {
        const B = sorted[j];
        const bb = boxes.get(B.key)!;
        if (bb[0] > ba[3]) break;
        if (bb[1] > ba[4] || ba[1] > bb[4] || bb[2] > ba[5] || ba[2] > bb[5]) continue;
        if (A.instance === B.instance && A.key === B.key) continue;
        const wallPair = useVoxel && method.walls === "voxel" && (A === enclosure || B === enclosure);
        if (wallPair) continue;
        candidates++;
        const [X, Y] = A.key < B.key ? [A, B] : [B, A];
        const ck = `${X.key}~${Y.key}|${round6(relative(world.get(X.key)!, world.get(Y.key)!))}`;
        let res = cache.get(ck);
        if (res === undefined) {
          res = testPair(X, Y, world.get(X.key)!, world.get(Y.key)!, { ...INTERFERENCE_DEFAULTS, ...opts }) ?? null;
          cache.set(ck, res);
          tested++;
        } else reused++;
        if (res) {
          const intended = intendedOf(X, Y);
          hits.push({ a: X.key, b: Y.key, ...res, ...(intended ? { intended } : {}), method: "bvh" });
        }
      }
    }
    if (useVoxel && method.walls === "voxel") {
      const encInv = invertRigid(world.get(enclosure!.key)!);
      for (const b of active) {
        if (b === enclosure) continue;
        const id = `${b.key}|${round6(mul(encInv, world.get(b.key)!))}`;
        const h = voxelHits.get(id);
        if (!h) continue;
        const intended = intendedOf(enclosure!, b);
        // the hit point back to world from the enclosure frame
        const at = h.at ? applyRM(world.get(enclosure!.key)!, h.at).map((x) => Math.round(x * 100) / 100) : undefined;
        hits.push({ ...h, ...(at ? { at } : {}), ...(intended ? { intended } : {}) });
      }
    }
    hits.sort((x, y) => (x.status === y.status ? 0 : x.status === "interference" ? -1 : 1) || Number(!!x.intended) - Number(!!y.intended) || y.depthMm - x.depthMm);
    for (const h of hits) {
      if (h.status === "contact") counts.contact++;
      else if (h.intended) counts.intendedInterference++;
      else counts.interference++;
    }
    reports.push({ id: k.id, label: k.label, t: Math.round(k.t * 1e6) / 1e6, ms: Math.round((performance.now() - t0) * 10) / 10, candidates, tested, reused, hits, excluded: [...pose.apart].filter((x) => loaded.bodies.some((b) => b.key === x)) });
  }
  return {
    schema: INTERFERENCE_SCHEMA,
    method,
    defaults: { ...INTERFERENCE_DEFAULTS, voxel: VOXEL_DEFAULTS },
    bodies: loaded.bodies.length,
    triangles: loaded.triangles,
    timings: { loadMs: loaded.loadMs, bvhMs: loaded.bvhMs, checkMs: Math.round(performance.now() - start - loaded.loadMs - loaded.bvhMs) },
    keyframes: reports,
    counts,
    skipped: loaded.skipped,
    ...(truncated ? { truncated } : {}),
  };
}
